/* Cloze skills, one lesson each: CZ2 collocations, CZ3 prepositions, CZ4 connectors, CZ5 tense and verb form,
   CZ6 near-synonyms by meaning and tone, CZ7 articles and determiners. All sentences are original.
   The first table of each lesson feeds a Lab deck (lab.js), so its rows must have one answer only. */
LESSONS.push(
{id:"CZ2", heat:2, title:"Collocations and fixed pairs", hi:"कोलोकेशन — साथ चलने वाले शब्द", blocks:[
  {k:"hot", h:"Nearly every cloze passage has one blank decided by a <b>collocation</b> — a word that habitually goes with another: <i>heavy rain</i>, <i>make a decision</i>, <i>pay attention</i>, <i>raise awareness</i>. The wrong options are often near-synonyms that mean the same but are simply not said."},
  {k:"story", h:"<p>Why do we say <i>heavy rain</i> and not <i>strong rain</i>, or <i>strong tea</i> and not <i>powerful tea</i>? There is no rule of logic — English speakers have just always put these words together. Such habitual partners are called <b>collocations</b>.</p><p>The commonest kind in a cloze test is a <b>verb with a noun</b>: we <i>make</i> a mistake but <i>do</i> homework, <i>take</i> a break but <i>pay</i> attention. The second kind is an <b>adjective with a noun</b> (<i>heavy traffic</i>, <i>high temperature</i>). The third is a <b>fixed pair</b> joined by <i>and</i> (<i>safe and sound</i>, <i>pros and cons</i>), whose order never changes.</p><p>You cannot work these out — you learn them as whole phrases, the way you learn a phone number.</p>", key:"Learn the phrase, not the single word: ‘make a mistake’, ‘do homework’, ‘pay attention’."},
  {k:"table", title:"Verb + noun: which verb goes with it?", head:["Words","Verb","Example"], rows:[
    ["___ a mistake","make","Everyone makes a mistake now and then."],
    ["___ an effort","make","She made an effort to speak slowly."],
    ["___ a wish","make","Close your eyes and make a wish."],
    ["___ progress","make","The patient is making good progress."],
    ["___ the bed","make","He makes the bed every morning."],
    ["___ a noise","make","Please do not make a noise in the library."],
    ["___ homework","do","The children do their homework after tea."],
    ["___ the dishes","do","I will do the dishes tonight."],
    ["___ (someone) a favour","do","Could you do me a favour?"],
    ["___ business with (a firm)","do","We have done business with them for years."],
    ["___ research","do","She is doing research on soil health."],
    ["___ a photograph","take","Tourists took photographs of the fort."],
    ["___ a break (a short rest)","take","Let us take a short break."],
    ["___ a nap","take","Grandfather takes a nap after lunch."],
    ["___ place (happen)","take","The meeting will take place on Friday."],
    ["___ attention","pay","Pay attention to the road signs."],
    ["___ tribute","pay","The nation paid tribute to the soldiers."],
    ["___ the price","pay","The town paid the price for its carelessness."],
    ["___ a fine","pay","He paid a fine for parking on the footpath."],
    ["___ a cold","catch","She caught a cold in the rain."],
    ["___ fire (begin to burn)","catch","Dry grass can catch fire easily."],
    ["___ a glimpse","catch","We caught a glimpse of the tiger."],
    ["___ a secret","keep","Can you keep a secret?"],
    ["___ a diary","keep","He kept a diary during the trip."],
    ["___ calm","keep","Keep calm and leave the building."],
    ["___ track of","keep","Keep track of your expenses."],
    ["___ awareness","raise","The campaign raised awareness about clean water."],
    ["___ funds","raise","Students raised funds for the flood victims."],
    ["___ the alarm","raise","The guard raised the alarm when he saw smoke."]]},
  {k:"table", title:"Fixed pairs: the order never changes", head:["Begins","Ends with","Meaning"], rows:[
    ["bread and …","butter","one’s means of living"],
    ["safe and …","sound","unharmed"],
    ["null and …","void","having no legal force"],
    ["odds and …","ends","small things of little value"],
    ["pros and …","cons","arguments for and against"],
    ["ups and …","downs","good and bad times"],
    ["law and …","order","the keeping of public peace"],
    ["wear and …","tear","damage from ordinary use"],
    ["by and …","large","on the whole"],
    ["now and …","then","sometimes"],
    ["hale and …","hearty","healthy and strong"],
    ["kith and …","kin","friends and relatives"],
    ["part and …","parcel","an essential part"],
    ["first and …","foremost","most importantly"],
    ["spick and …","span","neat and clean"],
    ["hue and …","cry","a loud public protest"]]},
  {k:"table", title:"Adjective + noun: the natural partner", head:["Say","Not","Note"], rows:[
    ["heavy rain, heavy traffic","strong rain, big traffic","<i>heavy</i> for a large amount"],
    ["strong tea, strong coffee","powerful tea","<i>strong</i> for a lot of flavour"],
    ["high temperature, high price","tall temperature, big price","<i>high</i> for levels and amounts"],
    ["dense fog, dense forest","crowded fog","<i>thick fog</i> is also right"],
    ["deep sleep, sound sleep","strong sleep","—"],
    ["sharp memory, sharp rise","pointed memory","<i>sharp</i> for quick or clear"],
    ["hard work","heavy work (for effort)","<i>hard</i> for effort"],
    ["bitter truth","sour truth","—"],
    ["narrow escape","thin escape","only just escaped"],
    ["golden opportunity","silver opportunity","a very good chance"],
    ["open secret","public secret","something everyone knows"]]},
  {k:"ex", h:"<p><b>Worked example.</b> ‘After weeks of talks, the panel finally ___ a decision on the new bus routes.’ Options: <i>made / did / gave / put</i>.</p><p><i>Decision</i> goes with <i>make</i> (and, in Indian and British English, <i>take</i>). <i>Did a decision</i>, <i>gave a decision</i> and <i>put a decision</i> are not said. Answer: <b>made</b>.</p>"},
  {k:"trick", h:"<b>MAKE</b> creates something new (a cake, a plan, a noise, a profit). <b>DO</b> is for work, tasks and duties (homework, the dishes, one’s duty, a favour). When in doubt: <i>make</i> = produce, <i>do</i> = perform."},
  {k:"trap", h:"<b>Commit</b> goes with <i>crime</i>, <i>murder</i> and <i>suicide</i>, but we <b>make</b> a mistake. We <b>raise</b> funds and awareness (the verb takes an object) — things <b>rise</b> by themselves (prices rise). <b>Lodge</b> or <b>file</b> a complaint, not <i>put</i> one."}
], sum:["A collocation is a word pair English speakers habitually use: heavy rain, strong tea, make a decision.","make — a mistake, an effort, a profit, progress, a noise; do — homework, the dishes, a favour, one’s best, research.","take — a photograph, a break, place; pay — attention, tribute, a fine, the price; catch — a cold, fire, a glimpse.","keep — a secret, a diary, calm, track of; raise — awareness, funds, the alarm; give — birth to, rise to.","Fixed pairs never change order: safe and sound, null and void, pros and cons, law and order, wear and tear.","Commit a crime but make a mistake; raise funds but prices rise."]},

{id:"CZ3", heat:2, title:"Prepositions in context", hi:"प्रसंग में पूर्वसर्ग (Prepositions)", blocks:[
  {k:"hot", h:"About one blank in three of a cloze passage is a <b>preposition</b>. Most are decided by the word just before it — <i>depend <b>on</b></i>, <i>accused <b>of</b></i>, <i>prefer X <b>to</b> Y</i> — and the rest by time and place (<i>at</i> 6 o’clock, <i>on</i> Monday, <i>in</i> June)."},
  {k:"story", h:"<p>A preposition is a small word that links a noun to the rest of the sentence: <i>in</i>, <i>on</i>, <i>at</i>, <i>of</i>, <i>for</i>, <i>with</i>, <i>from</i>, <i>to</i>. It is the hardest blank to guess, because the meaning seldom helps — we are <i>interested <b>in</b></i> music but <i>fond <b>of</b></i> it, and both mean almost the same.</p><p>The way through is to learn each word <b>with</b> its preposition, as one unit: not <i>accuse</i> but <i>accuse … of</i>; not <i>prefer</i> but <i>prefer … to</i>. For time and place, three words do most of the work: <b>at</b> for a point, <b>on</b> for a day or a surface, <b>in</b> for a longer period or an enclosed space.</p>", key:"Learn the word and its preposition together: depend on, accused of, prefer to, interested in."},
  {k:"table", title:"Words and the preposition they take", head:["Word","Preposition","Example"], rows:[
    ["accused ___ (a crime)","of","He was accused of theft."],
    ["afraid ___ (the dark)","of","The child is afraid of the dark."],
    ["aware ___ (the risk)","of","Are you aware of the risk?"],
    ["capable ___ (doing it)","of","She is capable of leading the team."],
    ["fond ___ (music)","of","He is fond of old songs."],
    ["proud ___ (her work)","of","She is proud of her work."],
    ["ashamed ___ (his lie)","of","He was ashamed of his lie."],
    ["jealous ___ (his success)","of","Some were jealous of his success."],
    ["addicted ___ (mobile games)","to","Many teenagers are addicted to mobile games."],
    ["married ___ (a doctor)","to","She is married to a doctor."],
    ["superior ___ (the old model)","to","This phone is superior to the old model."],
    ["similar ___ (mine)","to","Your bag is similar to mine."],
    ["accustomed ___ (the heat)","to","We are accustomed to the heat."],
    ["prefer tea ___ coffee","to","I prefer tea to coffee."],
    ["object ___ (the plan)","to","The villagers objected to the plan."],
    ["devoted ___ (her students)","to","She is devoted to her students."],
    ["interested ___ (science)","in","He is interested in science."],
    ["rich ___ (minerals)","in","The region is rich in minerals."],
    ["believe ___ (hard work)","in","I believe in hard work."],
    ["lacking ___ (courage)","in","He is not lacking in courage."],
    ["confidence ___ (oneself)","in","Have confidence in yourself."],
    ["participate ___ (the debate)","in","Ten schools participated in the debate."],
    ["depend ___ (the weather)","on","Our plans depend on the weather."],
    ["insist ___ (paying)","on","She insisted on paying."],
    ["rely ___ (friends)","on","You can rely on your friends."],
    ["keen ___ (cricket)","on","My brother is keen on cricket."],
    ["comment ___ (the issue)","on","The minister refused to comment on the issue."],
    ["arrive ___ a conclusion","at","The panel arrived at a conclusion."],
    ["stare ___ (the stranger)","at","Do not stare at strangers."],
    ["comply ___ (the rules)","with","All shops must comply with the rules."],
    ["cope ___ (stress)","with","Exercise helps us cope with stress."],
    ["filled ___ (water)","with","The pot was filled with water."],
    ["suffer ___ (fever)","from","She is suffering from fever."],
    ["refrain ___ (smoking)","from","Please refrain from smoking."],
    ["abstain ___ (alcohol)","from","He abstains from alcohol."],
    ["recover ___ (an illness)","from","He has recovered from the illness."],
    ["famous ___ (its sweets)","for","The town is famous for its sweets."],
    ["eligible ___ (the post)","for","Graduates are eligible for the post."],
    ["apologise ___ (the delay)","for","The airline apologised for the delay."],
    ["burst ___ tears","into","The child burst into tears."],
    ["crash ___ (a wall)","into","The car crashed into a wall."]]},
  {k:"table", title:"Time and place: at, on, in", head:["Preposition","Used for","Examples"], rows:[
    ["at","A point of time; a point or address","at 6 a.m., at noon, at night; at the station, at 12 Park Road"],
    ["on","Days and dates; a surface","on Monday, on 15 August; on the table, on the wall"],
    ["in","Months, years, seasons, parts of the day; inside a space","in June, in 2024, in winter, in the morning; in the room, in Delhi"],
    ["since","A point in the past up to now (with the present perfect)","I have lived here since 2015."],
    ["for","A length of time","He has been ill for three weeks."],
    ["by","Not later than","Submit the form by Friday."],
    ["into","Movement to the inside","She walked into the room."],
    ["between / among","Two things / more than two","between the two brothers; among the five friends"]]},
  {k:"ex", h:"<p><b>Worked example.</b> ‘The success of the scheme depends ___ the support of local people.’ Options: <i>on / in / at / to</i>.</p><p>Look only at the word before the blank: <i>depend</i> always takes <b>on</b> (or <i>upon</i>). Answer: <b>on</b>.</p>"},
  {k:"trick", h:"<b>“Prefer TO, not THAN”</b>: I prefer tea <i>to</i> coffee. <b>“Since a point, for a period”</b>: since 2015, for ten years. <b>“Into for motion, in for position”</b>: he jumped into the pool; he is swimming in the pool."},
  {k:"trap", h:"<b>Prefer … to</b>, not <i>prefer … than</i>. <b>Superior/inferior/senior/junior to</b>, not <i>than</i>. <b>Accused of</b> but <b>charged with</b>. <b>Congratulate on</b> a success. <b>Discuss</b> and <b>enter</b> take no preposition: we discuss a plan (not <i>discuss about</i>), enter a room (not <i>enter into</i>)."}
], sum:["Most prepositions are fixed by the word before them: depend on, accused of, interested in, prefer to.","of — afraid, aware, capable, fond, proud, ashamed, jealous; to — addicted, married, superior, similar, accustomed, object.","in — interested, rich, believe, succeed, confidence, participate; on — depend, insist, rely, keen, congratulate (on a success), comment.","with — comply, cope, filled; from — suffer, refrain, abstain, recover; for — famous, eligible, apologise.","Time: at a point, on a day or date, in a month, year or season; since a point, for a period.","Discuss and enter take no preposition; prefer and superior take to, not than."]},

{id:"CZ4", heat:3, title:"Linking words and connectors", hi:"संयोजक शब्द — however, therefore, despite, although", blocks:[
  {k:"hot", h:"One or two blanks in almost every cloze passage need a <b>linking word</b>. The test is about <b>logic</b> — does the next idea go against, follow from, or add to the last one? — and then about <b>grammar</b>: <i>despite</i> takes a noun, <i>although</i> takes a clause."},
  {k:"story", h:"<p>Linking words are the road signs of a passage. <b>However</b> says ‘turn: the next idea goes against the last’. <b>Therefore</b> says ‘this follows from what came before’. <b>Moreover</b> says ‘one more point in the same direction’.</p><p>So the method is simple. Read the sentence before the blank and the sentence after it, and ask what the second does to the first. Does it <b>contrast</b> with it? Is it a <b>result</b>? An <b>addition</b>? A <b>reason</b>, a <b>condition</b>, an <b>example</b>? Once you know the job, only one or two options remain, and the grammar picks between them.</p><p>Example: ‘It rained heavily. ___, the match went ahead.’ A match going ahead in heavy rain is unexpected — a contrast — so <i>Nevertheless</i> or <i>However</i>, not <i>Therefore</i>.</p>", key:"First decide the job (contrast, result, addition, reason, condition, purpose, example, time), then check the grammar."},
  {k:"table", title:"Connectors and their jobs", head:["Connector","Job","Example"], rows:[
    ["however","Contrast","The plan was cheap; however, it failed."],
    ["although","Contrast","Although it rained, the match went ahead."],
    ["despite","Contrast","Despite the rain, the match went ahead."],
    ["in spite of","Contrast","In spite of his injury, he finished the race."],
    ["nevertheless","Contrast","He was tired; nevertheless, he kept working."],
    ["whereas","Contrast","Cities are crowded, whereas villages are quiet."],
    ["on the other hand","Contrast","City life is fast; village life, on the other hand, is slow."],
    ["therefore","Result","The roads were flooded; therefore, schools were shut."],
    ["consequently","Result","The factory polluted the river; consequently, the fish died."],
    ["hence","Result","The shop was crowded; hence, we left."],
    ["as a result","Result","Prices rose; as a result, sales fell."],
    ["moreover","Addition","The scheme is cheap; moreover, it is quick."],
    ["furthermore","Addition","The road is narrow; furthermore, it has no lights."],
    ["in addition","Addition","It helps the poor; in addition, it creates jobs."],
    ["besides","Addition","Besides English, she speaks Tamil."],
    ["because","Reason","He was late because the bus broke down."],
    ["because of","Reason","The match was called off because of rain."],
    ["owing to","Reason","Owing to heavy traffic, we were late."],
    ["unless","Condition","You will miss the bus unless you hurry."],
    ["provided that","Condition","You may go, provided that you finish your work."],
    ["in case","Condition","Take an umbrella in case it rains."],
    ["so that","Purpose","She saved money so that she could study abroad."],
    ["in order to","Purpose","He left early in order to catch the train."],
    ["lest","Purpose","Walk carefully lest you should slip."],
    ["for instance","Example","Some fruits, for instance amla, are rich in vitamin C."],
    ["such as","Example","Millets such as ragi need little water."],
    ["meanwhile","Time","The rice was cooking; meanwhile, she cut the vegetables."],
    ["subsequently","Time","He joined as a clerk and was subsequently promoted."]]},
  {k:"table", title:"Words that come in pairs", head:["First part","Second part","Example"], rows:[
    ["No sooner …","than","No sooner had the bell rung than the children ran out."],
    ["Hardly …","when","Hardly had we arrived when it began to rain."],
    ["Scarcely …","when","Scarcely had he sat down when the phone rang."],
    ["Not only …","but also","She is not only a singer but also a dancer."],
    ["Either …","or","Either you pay now or you pay a fine."],
    ["Neither …","nor","Neither the teacher nor the students knew."],
    ["Both …","and","Both rice and wheat are grown here."],
    ["Whether …","or","Whether you agree or not, the rule stays."],
    ["So + adjective …","that","He was so tired that he fell asleep."],
    ["Rather …","than","I would rather walk than wait."]]},
  {k:"table", title:"The grammar of connectors", head:["Connector","What follows it","Right / wrong"], rows:[
    ["despite, in spite of","A noun or -ing (no clause)","Despite the rain ✓ · Despite it rained ✗"],
    ["although, though, even though","A full clause","Although it rained ✓ · Although the rain ✗"],
    ["because of, owing to, due to","A noun","because of the strike ✓"],
    ["because","A full clause","because the workers went on strike ✓"],
    ["however, therefore, moreover","Usually a new clause; set off by commas","…; however, it failed."],
    ["lest","should + V1 (or the plain verb)","lest he should fall ✓ · lest he does not fall ✗"],
    ["unless","A positive clause (it already means ‘if not’)","unless you hurry ✓ · unless you do not hurry ✗"]]},
  {k:"ex", h:"<p><b>Worked example.</b> ‘___ his injury, he completed the race.’ Options: <i>Despite / Although / However / Because</i>.</p><p>Job: an injured man finishing a race is a <b>contrast</b> — so <i>Despite</i>, <i>Although</i> or <i>However</i>. Grammar: what follows is a noun (<i>his injury</i>), not a clause, so <i>Although</i> fails; <i>However</i> cannot join a noun to a clause. Answer: <b>Despite</b>.</p>"},
  {k:"trick", h:"<b>“Despite takes a thing, although takes a sentence.”</b> Despite <i>the rain</i>; although <i>it rained</i>. And <b>never</b> write <i>despite of</i> — it is <i>despite</i> or <i>in spite of</i>."},
  {k:"trap", h:"<b>No sooner … than</b> (not <i>then</i> or <i>when</i>); <b>hardly / scarcely … when</b> (not <i>than</i>). <b>Unless</b> and <b>lest</b> already contain ‘not’, so do not add another <i>not</i>. <b>Although … but</b> is wrong — use one or the other."}
], sum:["First find the job of the blank: contrast, result, addition, reason, condition, purpose, example or time.","Contrast: however, although, despite, in spite of, nevertheless, whereas, on the other hand.","Result: therefore, consequently, hence, as a result. Addition: moreover, furthermore, in addition, besides.","Despite and in spite of take a noun; although takes a clause. Never ‘despite of’.","No sooner … than; hardly / scarcely … when; not only … but also; either … or; neither … nor.","Unless and lest are already negative; do not add ‘not’ after them."]},

{id:"CZ5", heat:2, title:"Tense and verb form from the context", hi:"प्रसंग से काल (Tense) और क्रिया-रूप", blocks:[
  {k:"hot", h:"When the options are four forms of one verb (<i>has been working / is working / was working / works</i>), the blank is about <b>tense</b>. The passage gives the answer through <b>signal words</b> (<i>since</i>, <i>by the time</i>, <i>yesterday</i>) and through the tense of the sentences around it."},
  {k:"story", h:"<p>A passage keeps to one time frame. A story about the freedom movement is told in the past; an article on climate change speaks of the present and the future. So the first clue to a tense blank is <b>the tense of the whole passage</b> — which you noticed on your first reading.</p><p>The second clue is a <b>signal word</b>. <i>Since 2018</i> or <i>for three years</i> joined to ‘now’ calls for the present perfect (<i>has worked</i>, <i>has been working</i>). <i>By the time</i> + a past event calls for the past perfect (<i>had left</i>). <i>Yesterday</i>, <i>ago</i>, <i>last year</i> call for the simple past.</p><p>The third clue is a <b>fixed verb pattern</b>: <i>look forward to</i> takes <i>-ing</i>; <i>used to</i> takes the plain verb; <i>make someone</i> takes the plain verb without <i>to</i>.</p>", key:"Tense of the passage first, then the signal word, then the fixed pattern."},
  {k:"table", title:"Signal words and the tense they call for", head:["Signal","Tense or form","Example"], rows:[
    ["every day, usually, always (a habit)","Simple present","She walks for an hour every morning."],
    ["a universal truth","Simple present","Water boils at 100 °C."],
    ["now, at the moment, Look!","Present continuous","Look! The children are playing."],
    ["since 2018 / for three years (up to now)","Present perfect","She has worked here since 2018."],
    ["just, already, yet","Present perfect","The train has just left."],
    ["yesterday, ago, last year, in 2010","Simple past","He visited Agra last year."],
    ["while + an action going on in the past","Past continuous","While I was cooking, the lights went out."],
    ["by the time / before + a past event","Past perfect","The train had left before we arrived."],
    ["tomorrow, next week","Simple future","We will meet tomorrow."],
    ["at this time tomorrow","Future continuous","At this time tomorrow I will be flying to Chennai."],
    ["by next year / by the time + a future event","Future perfect","By next year she will have finished the course."],
    ["If + simple past (unreal now)","would + V1","If I were rich, I would build a school."],
    ["If + had + V3 (unreal past)","would have + V3","If he had studied, he would have passed."],
    ["It is high time …","Past form","It is high time we left."]]},
  {k:"table", title:"The verb form after certain words", head:["Word or pattern","Form that follows","Example"], rows:[
    ["look forward to","-ing","I look forward to meeting you."],
    ["be used to (be familiar with)","-ing","He is used to getting up early."],
    ["avoid","-ing","She avoided answering."],
    ["enjoy","-ing","They enjoy reading."],
    ["mind","-ing","Would you mind closing the door?"],
    ["finish","-ing","He finished writing the report."],
    ["used to (past habit)","V1 (bare)","He used to walk to school."],
    ["let (someone)","V1 (bare)","Let him speak."],
    ["make (someone)","V1 (bare)","The teacher made us repeat the poem."],
    ["had better","V1 (bare)","You had better leave now."],
    ["would rather","V1 (bare)","I would rather stay home."],
    ["decide","to + V1","She decided to join the course."],
    ["want","to + V1","They want to win."],
    ["refuse","to + V1","He refused to sign."],
    ["hope","to + V1","We hope to see you soon."],
    ["have (something) …","V3 (past participle)","I had my watch repaired."],
    ["get (something) …","V3 (past participle)","She got her eyes tested."]]},
  {k:"ex", h:"<p><b>Worked example.</b> ‘By the time the fire brigade arrived, the house ___ down.’ Options: <i>had burnt / has burnt / will burn / is burning</i>.</p><p>Signal: <i>by the time</i> + a past event (<i>arrived</i>). The burning was complete <b>before</b> that past moment — past perfect. Answer: <b>had burnt</b>.</p>"},
  {k:"trick", h:"<b>“Used TO + V1, used to + ING”</b>: <i>I used to walk</i> (I no longer do) but <i>I am used to walking</i> (it is normal for me). The little word <b>am / is / are</b> before <i>used to</i> changes everything."},
  {k:"trap", h:"<b>Since</b> needs the present perfect, not the simple present: <i>I have lived here since 2015</i>, not <i>I live here since 2015</i>. In an <b>if</b>-clause about the future, use the simple present: <i>If it rains tomorrow</i>, not <i>If it will rain</i>. After <b>wish</b> about the past, use the past perfect: <i>I wish I had known</i>."}
], sum:["Keep to the tense of the passage unless a signal word changes it.","since / for + up to now → present perfect; by the time + past → past perfect; yesterday, ago → simple past.","If + present → will; if + past → would + V1; if + had + V3 → would have + V3.","look forward to, be used to, avoid, enjoy, mind, finish → -ing.","used to, let, make, had better, would rather → V1; decide, want, refuse, hope → to + V1; have/get something → V3.","It is high time and wish (present) take the past form."]},

{id:"CZ6", heat:3, title:"Near-synonyms: the right word by meaning and tone", hi:"समान-अर्थी शब्दों में सही शब्द — अर्थ और भाव", blocks:[
  {k:"hot", h:"Some blanks offer four words of about the same meaning — <i>famous, renowned, notorious, celebrated</i>. Only one fits the <b>shade</b> of the sentence (good or bad), or the exact <b>meaning</b> (<i>economic</i> vs <i>economical</i>). Look-alike pairs (<i>affect/effect</i>, <i>principal/principle</i>) are also tested this way."},
  {k:"story", h:"<p>Words that look alike in a dictionary can feel very different in a sentence. A <i>thrifty</i> man and a <i>miserly</i> man both spend little — but the first is praised and the second is blamed. <i>Childlike</i> wonder is charming; <i>childish</i> behaviour is silly. <i>Famous</i> and <i>notorious</i> both mean ‘well known’, but only a criminal is notorious.</p><p>So when the options look like synonyms, ask two questions. First, <b>is the sentence approving or disapproving?</b> Words such as <i>finally arrested</i>, <i>shameful</i> or <i>praised</i> tell you. Second, <b>what exactly is meant?</b> A car that saves petrol is <i>economical</i>; a crisis about money and jobs is <i>economic</i>.</p>", key:"Ask: is the sentence praising or blaming? Then pick the word with the same shade and the exact meaning."},
  {k:"table", title:"Look-alikes and near-synonyms in a sentence", head:["Sentence","Right word","Look-alike (wrong here)","Why"], rows:[
    ["The ___ smuggler was finally arrested.","notorious","famous","Notorious = well known for something bad."],
    ["The scientist is ___ for her work on clean water.","renowned","notorious","Renowned = famous for something good."],
    ["He never wastes money but helps the needy; he is ___.","thrifty","miserly","Thrifty is praise; miserly is blame."],
    ["Throwing a tantrum over a game is ___ behaviour.","childish","childlike","Childish = silly; childlike = innocent."],
    ["She looked at the world with ___ wonder.","childlike","childish","Childlike wonder is fresh and innocent."],
    ["Be ___ to the feelings of others.","sensitive","sensible","Sensitive = aware of feelings."],
    ["It would be ___ to carry an umbrella today.","sensible","sensitive","Sensible = wise, reasonable."],
    ["This car is very ___ on petrol.","economical","economic","Economical = saving money."],
    ["The country faces an ___ crisis.","economic","economical","Economic = about the economy."],
    ["Loud noise can ___ your hearing.","affect","effect","Affect is the verb (to influence)."],
    ["The new rule had a good ___ on traffic.","effect","affect","Effect is the noun (a result)."],
    ["The ___ of the school spoke to parents.","principal","principle","Principal = head of a school."],
    ["Lying is against my ___.","principles","principals","Principle = a rule of conduct."],
    ["Everyone came ___ Ravi.","except","accept","Except = leaving out."],
    ["Please ___ my apology.","accept","except","Accept = take willingly."],
    ["Do not ___ your ticket.","lose","loose","Lose = misplace."],
    ["The screw is ___; tighten it.","loose","lose","Loose = not tight."],
    ["The red scarf is a perfect ___ to her dress.","complement","compliment","Complement = something that completes."],
    ["He paid her a ___ on her speech.","compliment","complement","Compliment = words of praise."],
    ["A storm is ___; boats must return.","imminent","eminent","Imminent = about to happen."],
    ["Dr Rao is an ___ surgeon.","eminent","imminent","Eminent = distinguished."],
    ["The equator is an ___ line.","imaginary","imaginative","Imaginary = not real."],
    ["The child wrote an ___ story.","imaginative","imaginary","Imaginative = full of fresh ideas."],
    ["The damage was ___ — a tiny scratch.","negligible","negligent","Negligible = too small to matter."],
    ["The guard was ___ and left the gate open.","negligent","negligible","Negligent = careless in duty."],
    ["Masked men ___ the bank.","robbed","stole","We rob a person or place; we steal a thing."],
    ["Someone ___ my bicycle.","stole","robbed","We steal a thing from someone."]]},
  {k:"table", title:"Same idea, different shade", head:["Word","Shade","Its partner with the other shade"], rows:[
    ["thrifty","Approving (+)","miserly, stingy"],
    ["miserly","Disapproving (−)","thrifty"],
    ["confident","Approving (+)","arrogant"],
    ["arrogant","Disapproving (−)","confident"],
    ["firm","Approving (+)","stubborn, obstinate"],
    ["stubborn","Disapproving (−)","firm, determined"],
    ["curious","Approving (+)","nosy"],
    ["nosy","Disapproving (−)","curious"],
    ["slim","Approving (+)","skinny"],
    ["skinny","Disapproving (−)","slim"],
    ["renowned","Approving (+)","notorious"],
    ["notorious","Disapproving (−)","renowned, famous"],
    ["childlike","Approving (+)","childish"],
    ["childish","Disapproving (−)","childlike"],
    ["courageous","Approving (+)","reckless"],
    ["reckless","Disapproving (−)","courageous, brave"],
    ["generous","Approving (+)","extravagant"],
    ["extravagant","Disapproving (−)","generous"],
    ["assertive","Approving (+)","aggressive"],
    ["aggressive","Disapproving (−)","assertive"],
    ["frank","Approving (+)","blunt, rude"],
    ["gracious","Approving (+)","haughty"],
    ["curt","Disapproving (−)","brief, polite"],
    ["diligent","Approving (+)","negligent"]]},
  {k:"ex", h:"<p><b>Worked example.</b> ‘Even after losing the final, the captain remained ___ and praised the winners.’ Options: <i>gracious / arrogant / bitter / sullen</i>.</p><p>The clue is <i>praised the winners</i> — an approving sentence. <i>Arrogant</i>, <i>bitter</i> and <i>sullen</i> are all disapproving and would not go with praising the rivals. Answer: <b>gracious</b>.</p>"},
  {k:"trick", h:"<b>“A-ffect is the A-ction (verb); E-ffect is the E-nd result (noun).”</b> <b>“The princi-PAL is your PAL”</b> (a person); a princi-PLE is a ru-LE."},
  {k:"trap", h:"<b>Famous</b> and <b>renowned</b> are for good fame; <b>notorious</b> and <b>infamous</b> for bad. <b>Rob</b> a person or a place; <b>steal</b> a thing. <b>Negligible</b> describes an amount; <b>negligent</b> describes a person."}
], sum:["When options look like synonyms, ask whether the sentence approves or disapproves.","Approving: thrifty, confident, firm, curious, slim, renowned, childlike, courageous, generous.","Disapproving: miserly, arrogant, stubborn, nosy, skinny, notorious, childish, reckless, extravagant.","affect (verb) / effect (noun); principal (head, main) / principle (rule); accept / except; lose / loose.","economical (saving money) / economic (of the economy); sensible (wise) / sensitive (feeling).","imminent (about to happen) / eminent (distinguished); negligible (tiny) / negligent (careless)."]},

{id:"CZ7", heat:1, title:"Articles and determiners", hi:"आर्टिकल और निर्धारक (a, an, the, few, little)", blocks:[
  {k:"hot", h:"Article blanks appear now and then: <b>a</b> or <b>an</b> (decided by the <b>sound</b>, not the letter), <b>the</b> for something particular or unique, or <b>no article</b>. Determiners such as <i>few / a few</i>, <i>little / a little</i>, <i>much / many</i> are tested in the same slot."},
  {k:"story", h:"<p><b>A</b> and <b>an</b> mean ‘one, any one’. Which you use depends on the first <b>sound</b> of the next word: <i>an</i> before a vowel sound (<i>an hour</i>, <i>an MBA</i>), <i>a</i> before a consonant sound (<i>a university</i>, <i>a one-rupee coin</i>). The spelling can mislead you; say the word aloud.</p><p><b>The</b> points to something particular — one the reader already knows, or one of a kind: <i>the sun</i>, <i>the Ganga</i>, <i>the Ramayana</i>, <i>the best student</i>.</p><p>Many nouns take <b>no article</b> when used in general: names of most countries and cities (<i>India</i>, <i>Mumbai</i>), languages (<i>Hindi</i>), games (<i>cricket</i>), meals (<i>breakfast</i>) and abstract ideas (<i>honesty</i>).</p>", key:"a/an by sound; the for particular or unique; no article for general names, games, meals and ideas."},
  {k:"table", title:"a or an: go by the sound", head:["Word","Article","Because it begins with the sound"], rows:[
    ["hour","an","‘our’ (silent h)"],
    ["honest man","an","‘on’ (silent h)"],
    ["honour","an","‘on’ (silent h)"],
    ["heir","an","‘air’ (silent h)"],
    ["hospital","a","‘h’ (h is sounded)"],
    ["hotel","a","‘h’ (h is sounded)"],
    ["university","a","‘yoo’ (a consonant sound)"],
    ["European","a","‘yoo’"],
    ["unique idea","a","‘yoo’"],
    ["uniform","a","‘yoo’"],
    ["useful book","a","‘yoo’"],
    ["one-rupee coin","a","‘wun’ (a consonant sound)"],
    ["umbrella","an","‘uh’ (a vowel sound)"],
    ["unusual habit","an","‘uh’"],
    ["MBA","an","‘em’"],
    ["MLA","an","‘em’"],
    ["FIR","an","‘ef’"],
    ["X-ray","an","‘eks’"],
    ["SSC exam","an","‘es’"],
    ["NGO","an","‘en’"],
    ["UPSC exam","a","‘yoo’"],
    ["orange","an","‘o’"],
    ["engineer","an","‘e’"]]},
  {k:"table", title:"the, or no article?", head:["Phrase","Article","Rule"], rows:[
    ["___ Ganga","the","Rivers take the."],
    ["___ Himalayas","the","Mountain ranges take the."],
    ["___ Mount Everest","no article","A single peak takes no article."],
    ["___ Indian Ocean","the","Oceans and seas take the."],
    ["___ sun","the","One of a kind."],
    ["___ India","no article","Most country names take no article."],
    ["___ United States","the","Names with States, Kingdom, Republic take the."],
    ["___ Ramayana","the","Holy books and epics take the."],
    ["___ best student","the","Superlatives take the."],
    ["___ rich (as a class)","the","the + adjective = a whole group of people."],
    ["play ___ cricket","no article","Games take no article."],
    ["play ___ flute","the","Musical instruments take the."],
    ["have ___ lunch","no article","Meals in general take no article."],
    ["___ honesty (in general)","no article","Abstract nouns in general take no article."],
    ["speak ___ Hindi","no article","A language name alone takes no article."],
    ["___ Taj Mahal","the","Famous buildings take the."],
    ["___ Mumbai","no article","City names take no article."],
    ["travel by ___ bus","no article","by + a means of transport."],
    ["___ Sahara","the","Deserts take the."],
    ["___ Times of India","the","Newspapers take the."],
    ["on ___ Monday (in general)","no article","Days of the week take no article."],
    ["___ north (a direction)","the","Directions take the: in the north."]]},
  {k:"table", title:"Determiners of amount", head:["Word","Used with","Example"], rows:[
    ["much / little / a little","Uncountable nouns (water, money, time)","There is little time left."],
    ["many / few / a few","Countable plural nouns (books, friends)","Only a few students came."],
    ["few / little","Negative: hardly any","Few people know this (almost nobody)."],
    ["a few / a little","Positive: some, a small number","I have a few friends here (I am not alone)."],
    ["each / every","Singular noun, singular verb","Every student has a card."],
    ["either / neither","One of two; singular verb","Either road leads to the station."],
    ["fewer / less","fewer + countable; less + uncountable","fewer cars, less traffic"]]},
  {k:"ex", h:"<p><b>Worked example.</b> ‘It was ___ unique chance to meet the scientist.’ Options: <i>a / an / much / any</i>.</p><p><i>Unique</i> starts with the sound ‘yoo’ — a consonant sound — so <b>a</b>, not <i>an</i>. <i>Much</i> and <i>any</i> do not fit a single countable noun here. Answer: <b>a</b>.</p>"},
  {k:"trick", h:"<b>“Say it, don’t spell it.”</b> Read the next word aloud: <i>an</i> hour, <i>a</i> university, <i>an</i> MLA, <i>a</i> one-way road. The letter does not decide — the sound does."},
  {k:"trap", h:"<b>Few</b> means ‘hardly any’ (negative); <b>a few</b> means ‘some’ (positive) — the same for <b>little / a little</b>. <i>Mount Everest</i> takes no article, but <i>the Himalayas</i> does. <i>The</i> + adjective (<i>the rich</i>, <i>the poor</i>) takes a <b>plural</b> verb: <i>The rich should help the poor</i>."}
], sum:["a before a consonant sound, an before a vowel sound: an hour, an MBA, a university, a one-rupee coin.","the: rivers, oceans, mountain ranges, deserts, holy books, newspapers, famous buildings, superlatives, unique things.","No article: most countries and cities, languages, games, meals, abstract nouns in general, single peaks.","the + adjective = a class of people with a plural verb: the rich, the poor.","few / little = hardly any; a few / a little = some.","much and little with uncountable nouns; many and few with countable plurals; fewer cars but less traffic."]}
);

QB.push(
/* CZ2 collocations */
["CZ2","Fill in the blank: ‘The weather office has warned of ___ rain in the coastal districts over the next two days.’",["heavy","strong","big","thick"],"The collocation is ‘heavy rain’; ‘strong rain’ and ‘big rain’ are not used."],
["CZ2","Fill in the blank: ‘After weeks of discussion, the committee finally ___ a decision on the new bus routes.’",["made","did","gave","put"],"We ‘make’ (or ‘take’) a decision; ‘did’, ‘gave’ and ‘put’ a decision are not English."],
["CZ2","Fill in the blank: ‘Passengers are requested to ___ attention to the safety instructions before take-off.’",["pay","make","take","keep"],"The collocation is ‘pay attention’."],
["CZ2","Fill in the blank: ‘My grandmother likes her tea ___, with very little milk and plenty of leaves.’",["strong","powerful","heavy","hard"],"Tea with a lot of flavour is ‘strong tea’; ‘powerful tea’ is not said."],
["CZ2","Fill in the blank: ‘The new campaign aims to ___ awareness about the dangers of drunk driving.’",["raise","rise","lift","grow"],"We ‘raise awareness’. ‘Rise’ takes no object — prices rise by themselves."],
["CZ2","Fill in the blank: ‘___ fog covered the highway, and drivers could barely see ten metres ahead.’",["Dense","Crowded","Strong","Hard"],"Thick, low-visibility fog is ‘dense fog’ (also ‘thick fog’)."],
["CZ2","Fill in the blank: ‘Despite the slowdown, the company ___ a healthy profit in the last quarter.’",["made","did","gave","built"],"We ‘make a profit’."],
["CZ2","Fill in the blank: ‘We must ___ our best to finish the project before the rains begin.’",["do","make","take","have"],"The phrase is ‘do one’s best’."],
["CZ2","Fill in the blank: ‘The thief was caught ___-handed while breaking the lock of the shop.’",["red","black","blue","white"],"‘Caught red-handed’ means caught in the act."],
["CZ2","Fill in the blank: ‘For the fishermen of the coast, the sea is not a hobby; it is their bread and ___.’",["butter","jam","milk","salt"],"‘Bread and butter’ means one’s means of living."],
["CZ2","Fill in the blank: ‘After years of quarrelling over the land, the two brothers finally decided to bury the ___.’",["hatchet","sword","knife","spade"],"‘Bury the hatchet’ means to end a quarrel and make peace."],
["CZ2","Fill in the blank: ‘She has a ___ memory and never forgets a face she has seen once.’",["sharp","pointed","heavy","tall"],"A memory that is quick and clear is a ‘sharp memory’."],
["CZ2","Fill in the blank: ‘Passengers must ___ their seat belts fastened until the plane stops completely.’",["keep","hold","stay","remain"],"‘Keep something fastened’ is right; ‘stay’ and ‘remain’ cannot take an object here, and ‘hold’ is not used with ‘fastened’."],
["CZ2","Fill in the blank: ‘He ___ a cold after walking home in the rain without an umbrella.’",["caught","held","kept","made"],"We ‘catch a cold’."],
["CZ2","Fill in the blank: ‘The teacher asked the students to ___ their homework neatly in the new notebooks.’",["do","make","take","play"],"Tasks and work take ‘do’: ‘do homework’."],
["CZ2","Fill in the blank: ‘Rescue teams worked round the ___ to reach the miners trapped underground.’",["clock","day","watch","time"],"‘Round the clock’ means all day and all night."],
["CZ2","Fill in the blank: ‘It is an ___ secret in the town that the old bridge is unsafe; everyone knows it.’",["open","clear","public","plain"],"An ‘open secret’ is something supposed to be secret that everyone knows."],
["CZ2","Fill in the blank: ‘The shopkeeper has ___ a complaint with the police about the theft.’",["lodged","put","thrown","placed"],"We ‘lodge’ (or ‘file’) a complaint."],
["CZ2","Fill in the blank: ‘The police believe that the man ___ the crime alone, without any help.’",["committed","made","performed","acted"],"Crimes are ‘committed’."],
["CZ2","Fill in the blank: ‘The lost child was found the next morning, safe and ___.’",["sound","well","fine","secure"],"The fixed pair is ‘safe and sound’ — unharmed."],
["CZ2","Fill in the blank: ‘Before choosing a college, list the pros and ___ of each one.’",["cons","minus","against","negatives"],"The fixed pair is ‘pros and cons’ — arguments for and against."],
["CZ2","Fill in the blank: ‘The tourists ___ a glimpse of the snow leopard before it vanished among the rocks.’",["caught","held","kept","made"],"We ‘catch a glimpse’ of something."],
["CZ2","Fill in the blank: ‘The court declared the contract null and ___ because it had been signed under pressure.’",["void","empty","blank","zero"],"‘Null and void’ means having no legal force."],
["CZ2","Fill in the blank: ‘The whole nation ___ tribute to the soldiers who died defending the border.’",["paid","gave","made","took"],"The collocation is ‘pay tribute’."],

/* CZ3 prepositions */
["CZ3","Fill in the blank: ‘The officer was accused ___ taking a bribe from a contractor.’",["of","for","with","about"],"‘Accuse someone of something’. (We say ‘charged with’, but ‘accused of’.)"],
["CZ3","Fill in the blank: ‘My sister has been suffering ___ fever since Monday.’",["from","by","of","at"],"We ‘suffer from’ an illness."],
["CZ3","Fill in the blank: ‘The success of the water scheme depends ___ the support of the local people.’",["on","in","at","to"],"‘Depend’ always takes ‘on’ (or ‘upon’)."],
["CZ3","Fill in the blank: ‘Many office workers prefer walking ___ driving when the distance is short.’",["to","than","from","against"],"‘Prefer A to B’ — never ‘prefer … than’."],
["CZ3","Fill in the blank: ‘The students congratulated their teacher ___ her national award.’",["on","at","with","about"],"We ‘congratulate someone on’ a success."],
["CZ3","Fill in the blank: ‘Jharkhand is rich ___ minerals such as coal and iron ore.’",["in","of","at","by"],"‘Rich in’ something."],
["CZ3","Fill in the blank: ‘The meeting will begin ___ 10 a.m. sharp, so please be seated early.’",["at","on","in","since"],"A point of time takes ‘at’."],
["CZ3","Fill in the blank: ‘India became independent ___ 15 August 1947.’",["on","in","at","since"],"Dates take ‘on’."],
["CZ3","Fill in the blank: ‘We have lived in this town ___ 2015, and we still love it.’",["since","for","by","at"],"A point in the past up to now takes ‘since’ with the present perfect."],
["CZ3","Fill in the blank: ‘The old man has been ill ___ three weeks and needs rest.’",["for","since","from","by"],"A length of time takes ‘for’."],
["CZ3","Fill in the blank: ‘The little girl is afraid ___ the dark and sleeps with the light on.’",["of","from","with","by"],"‘Afraid of’ something."],
["CZ3","Fill in the blank: ‘Visitors are requested to refrain ___ smoking inside the museum.’",["from","of","to","against"],"‘Refrain from’ doing something."],
["CZ3","Fill in the blank: ‘The teacher divided the class ___ four groups for the project.’",["into","to","among","by"],"Splitting something into parts takes ‘divide into’."],
["CZ3","Fill in the blank: ‘The novel was translated ___ Bengali into English last year.’",["from","of","by","with"],"‘Translate from one language into another’."],
["CZ3","Fill in the blank: ‘Although it was late, she insisted ___ paying the whole bill herself.’",["on","for","to","at"],"‘Insist on’ something."],
["CZ3","Fill in the blank: ‘The new traffic law will come ___ force from the first of next month.’",["into","to","under","at"],"A law ‘comes into force’ when it starts to apply."],
["CZ3","Fill in the blank: ‘The doctor advised him to abstain ___ alcohol and fried food.’",["from","of","to","against"],"‘Abstain from’ something."],
["CZ3","Fill in the blank: ‘Your new school bag is very similar ___ the one I bought last year.’",["to","with","as","from"],"‘Similar to’ something."],
["CZ3","Fill in the blank: ‘This small town in Bengal is famous ___ its sweets.’",["for","of","with","about"],"‘Famous for’ something."],
["CZ3","Fill in the blank: ‘There is no point ___ arguing with him once he has made up his mind.’",["in","of","for","at"],"The phrase is ‘no point in doing something’."],
["CZ3","Fill in the blank: ‘After a long discussion, the panel arrived ___ a conclusion.’",["at","to","on","in"],"We ‘arrive at’ a conclusion or decision."],
["CZ3","Fill in the blank: ‘Hearing the sad news, the child burst ___ tears.’",["into","in","out","with"],"‘Burst into tears’ is the fixed phrase."],
["CZ3","Fill in the blank: ‘All factories must comply ___ the new rules on waste water.’",["with","to","by","for"],"‘Comply with’ a rule."],
["CZ3","Fill in the blank: ‘This new model is superior ___ the old one in every way.’",["to","than","from","over"],"‘Superior’ takes ‘to’, not ‘than’."],

/* CZ4 connectors */
["CZ4","Fill in the blank: ‘___ it rained heavily all morning, the match went ahead as planned.’",["Although","Because","Unless","Therefore"],"A match going ahead in heavy rain is a contrast; ‘although’ joins the two clauses."],
["CZ4","Fill in the blank: ‘The roads were flooded after the storm; ___, schools stayed closed for two days.’",["therefore","however","although","despite"],"Schools closing is the result of the floods: ‘therefore’."],
["CZ4","Fill in the blank: ‘___ his injury, the runner completed the race and won a medal.’",["Despite","Although","However","Because"],"A contrast followed by a noun (‘his injury’) needs ‘despite’; ‘although’ needs a clause."],
["CZ4","Fill in the blank: ‘The new method is cheap; ___, it can be put in place within a week.’",["moreover","however","nevertheless","otherwise"],"Both points favour the method, so the link is addition: ‘moreover’."],
["CZ4","Fill in the blank: ‘You will not get a seat on the night train ___ you book in advance.’",["unless","if","because","although"],"‘Unless’ means ‘if not’: no seat if you do not book."],
["CZ4","Fill in the blank: ‘She studied every evening ___ she could clear the exam in her first attempt.’",["so that","because","although","unless"],"The blank shows purpose: ‘so that’."],
["CZ4","Fill in the blank: ‘The medicine works well; ___, it has a few side effects that patients should know about.’",["however","therefore","thus","hence"],"Side effects go against ‘works well’: contrast."],
["CZ4","Fill in the blank: ‘Walk carefully on the wet floor ___ you should slip and fall.’",["lest","unless","so","until"],"‘Lest’ means ‘so that … not’ and goes with ‘should’."],
["CZ4","Fill in the blank: ‘___ the rains failed for the second year, the farmers did not lose hope.’",["Even though","Because","So that","In case"],"Not losing hope when the rains failed is a contrast; ‘even though’ takes the clause."],
["CZ4","Fill in the blank: ‘Not only did he win the race, ___ he also set a new state record.’",["but","and","yet","so"],"The pair is ‘not only … but (also)’."],
["CZ4","Fill in the blank: ‘The scheme has helped poor families; ___, it has created jobs in the villages.’",["in addition","instead","otherwise","on the contrary"],"A second benefit is added: ‘in addition’."],
["CZ4","Fill in the blank: ‘He was exhausted after the journey; ___, he kept working till midnight.’",["nevertheless","therefore","hence","thus"],"Working on while exhausted goes against expectation: ‘nevertheless’."],
["CZ4","Fill in the blank: ‘Take an umbrella ___ it rains on your way back.’",["in case","unless","although","so that"],"‘In case’ means as a precaution if something happens."],
["CZ4","Fill in the blank: ‘City life moves fast; village life, ___, keeps a slower pace.’",["on the other hand","as a result","for example","in addition"],"Two opposite pictures are compared: ‘on the other hand’."],
["CZ4","Fill in the blank: ‘___ the heavy traffic on the highway, we reached the station an hour late.’",["Owing to","Despite","Although","In spite"],"The traffic was the reason for being late: ‘owing to’ + noun. ‘In spite’ needs ‘of’."],
["CZ4","Fill in the blank: ‘He did not come to the meeting, ___ he had been invited twice.’",["although","because","so","therefore"],"Not coming despite two invitations is a contrast: ‘although’."],
["CZ4","Fill in the blank: ‘The factory kept pouring waste into the river; ___, the fish began to die.’",["consequently","nevertheless","although","instead"],"The fish dying is the result: ‘consequently’."],
["CZ4","Fill in the blank: ‘She is not only a good singer ___ a fine dancer.’",["but also","and also","as well","or also"],"The correlative pair is ‘not only … but also’."],
["CZ4","Fill in the blank: ‘No sooner had the bell rung ___ the children rushed out of the classroom.’",["than","then","when","that"],"‘No sooner’ pairs with ‘than’."],
["CZ4","Fill in the blank: ‘Hardly had we reached the platform ___ the train began to move.’",["when","than","then","that"],"‘Hardly’ pairs with ‘when’, not ‘than’."],
["CZ4","Fill in the blank: ‘Many millets, ___ ragi and bajra, need very little water to grow.’",["such as","as well","likewise","so as"],"‘Such as’ introduces examples."],
["CZ4","Fill in the blank: ‘Neither the manager ___ his assistant knew about the change in the schedule.’",["nor","or","and","but"],"‘Neither’ pairs with ‘nor’."],
["CZ4","Fill in the blank: ‘The shop was too crowded. ___, we decided to come back the next day.’",["Hence","Unless","Although","Despite"],"Coming back later is the result of the crowd: ‘hence’."],
["CZ4","Fill in the blank: ‘The water in the pot was boiling; ___, she chopped the vegetables for the curry.’",["meanwhile","therefore","unless","whereas"],"Two things happening at the same time: ‘meanwhile’."],

/* CZ5 tense and verb form */
["CZ5","Fill in the blank: ‘My cousin ___ in this company since 2018 and knows everyone here.’",["has been working","is working","was working","works"],"‘Since 2018’ up to now calls for the present perfect (continuous)."],
["CZ5","Fill in the blank: ‘By the time the fire brigade arrived, the old house ___ down completely.’",["had burnt","has burnt","will burn","is burning"],"The burning was over before a past moment (‘arrived’): past perfect."],
["CZ5","Fill in the blank: ‘If it rains tomorrow, we ___ the school picnic.’",["will cancel","would cancel","cancelled","had cancelled"],"A real future condition: if + present, will + V1."],
["CZ5","Fill in the blank: ‘If I were the principal, I ___ the library open on Sundays.’",["would keep","will keep","kept","keep"],"An unreal present condition (‘If I were’): would + V1."],
["CZ5","Fill in the blank: ‘Look! The children ___ in the rain outside the school gate.’",["are playing","play","have played","played"],"‘Look!’ signals an action happening now: present continuous."],
["CZ5","Fill in the blank: ‘Our teacher told us that the earth ___ round the sun once a year.’",["moves","is moving","has moved","had moved"],"A universal truth stays in the simple present even after ‘told’."],
["CZ5","Fill in the blank: ‘I look forward to ___ you at the annual function next week.’",["seeing","see","saw","have seen"],"‘Look forward to’ is followed by the -ing form."],
["CZ5","Fill in the blank: ‘When he was a boy, my father used to ___ five kilometres to school.’",["walk","walking","walked","walks"],"‘Used to’ for a past habit takes the plain verb (V1)."],
["CZ5","Fill in the blank: ‘Having lived on a farm for years, my uncle is used to ___ up before sunrise.’",["getting","get","got","have got"],"‘Be used to’ (be familiar with) is followed by -ing."],
["CZ5","Fill in the blank: ‘The teacher made the students ___ the poem twice before the bell rang.’",["recite","to recite","reciting","recited"],"‘Make someone’ is followed by the plain verb without ‘to’."],
["CZ5","Fill in the blank: ‘While I ___ dinner last night, the lights suddenly went out.’",["was cooking","am cooking","have cooked","will cook"],"An action going on in the past, broken by another (‘went out’): past continuous."],
["CZ5","Fill in the blank: ‘Ten years ago, our village ___ no proper road or bus service.’",["had","has","has had","will have"],"‘Ten years ago’ calls for the simple past."],
["CZ5","Fill in the blank: ‘By next March, the new metro line ___ for exactly two years.’",["will have been running","will run","has been running","had run"],"‘By’ + a future time with a length of time: future perfect continuous."],
["CZ5","Fill in the blank: ‘At the press meeting, the minister avoided ___ the question about prices.’",["answering","to answer","answer","answered"],"‘Avoid’ is followed by -ing."],
["CZ5","Fill in the blank: ‘After her degree, she decided ___ a course in data science.’",["to join","joining","join","joined"],"‘Decide’ is followed by ‘to’ + V1."],
["CZ5","Fill in the blank: ‘Wells are drying up; it is high time we ___ seriously about saving water.’",["thought","think","will think","are thinking"],"‘It is high time’ is followed by the past form."],
["CZ5","Fill in the blank: ‘I wish I ___ about the change in the exam date before I booked my ticket.’",["had known","knew","know","have known"],"A wish about the past takes the past perfect."],
["CZ5","Fill in the blank: ‘The new bridge over the river ___ by a team of local engineers last year.’",["was built","built","has built","is built"],"The bridge received the action in the past (‘last year’): past passive."],
["CZ5","Fill in the blank: ‘Neither the teacher nor the students ___ aware of the change in the timetable.’",["were","was","is","has been"],"With ‘neither … nor’, the verb agrees with the nearer subject (‘students’), so plural ‘were’."],
["CZ5","Fill in the blank: ‘He got his old car ___ at the new garage near the market.’",["repaired","repair","repairing","to repair"],"‘Get something done’ takes the past participle (V3)."],
["CZ5","Fill in the blank: ‘Every morning, my mother ___ for an hour before she makes breakfast.’",["walks","is walking","walked","has walked"],"A daily habit, with ‘makes’ in the present: simple present."],
["CZ5","Fill in the blank: ‘The train ___ before we reached the platform, so we waited for the next one.’",["had left","has left","leaves","will leave"],"The train left before another past action (‘reached’): past perfect."],
["CZ5","Fill in the blank: ‘If he had started earlier, he ___ the bus that left at nine.’",["would have caught","would catch","will catch","had caught"],"An unreal past condition (if + had + V3) takes would have + V3."],

/* CZ6 near-synonyms by meaning and tone */
["CZ6","Fill in the blank: ‘The ___ smuggler was finally arrested at the border after years on the run.’",["notorious","famous","renowned","celebrated"],"Fame for something bad is ‘notorious’; the others are words of praise."],
["CZ6","Fill in the blank: ‘The scientist is ___ across the world for her work on clean drinking water.’",["renowned","notorious","infamous","disreputable"],"Good fame is ‘renowned’; ‘notorious’ and ‘infamous’ mean known for something bad."],
["CZ6","Fill in the blank: ‘My grandfather is ___; he never wastes money, yet he gladly helps anyone in need.’",["thrifty","miserly","stingy","greedy"],"The sentence praises him, so the approving word ‘thrifty’ fits; ‘miserly’ and ‘stingy’ are blame."],
["CZ6","Fill in the blank: ‘Throwing a tantrum over a lost game of cards is ___ behaviour for a grown man.’",["childish","childlike","child-friendly","childhood"],"Silly behaviour is ‘childish’; ‘childlike’ is an approving word for innocence."],
["CZ6","Fill in the blank: ‘The painter looked at the world with a ___ wonder that made her pictures joyful.’",["childlike","childish","infantile","puerile"],"Fresh, innocent wonder is ‘childlike’; the other three are disapproving."],
["CZ6","Fill in the blank: ‘A good doctor is ___ to the fears of a frightened patient.’",["sensitive","sensible","sensory","sensational"],"Aware of feelings = ‘sensitive’; ‘sensible’ means wise."],
["CZ6","Fill in the blank: ‘With dark clouds gathering, it would be ___ to carry an umbrella today.’",["sensible","sensitive","sentimental","sensual"],"Wise or reasonable = ‘sensible’."],
["CZ6","Fill in the blank: ‘This small car is very ___; it runs about twenty-five kilometres on a litre of petrol.’",["economical","economic","economics","economist"],"Saving money or fuel = ‘economical’; ‘economic’ means relating to the economy."],
["CZ6","Fill in the blank: ‘The country is going through an ___ crisis, with prices rising and jobs falling.’",["economic","economical","economist","economising"],"A crisis of the economy is an ‘economic’ crisis."],
["CZ6","Fill in the blank: ‘Loud music played for hours can badly ___ your hearing.’",["affect","effect","infect","effort"],"The verb meaning ‘to influence or harm’ is ‘affect’."],
["CZ6","Fill in the blank: ‘The new one-way rule has had a good ___ on traffic near the market.’",["effect","affect","affection","efficacy"],"The noun meaning ‘result’ is ‘effect’; ‘efficacy’ means power to work and does not go with ‘had a good … on’."],
["CZ6","Fill in the blank: ‘The ___ of the school welcomed the parents at the annual day.’",["principal","principle","princely","principality"],"The head of a school is the ‘principal’; a ‘principle’ is a rule."],
["CZ6","Fill in the blank: ‘He refused to copy in the exam, as cheating was against his ___.’",["principles","principals","privileges","prejudices"],"Rules of right conduct are ‘principles’."],
["CZ6","Fill in the blank: ‘Everyone in the class went on the trip ___ Ravi, who was unwell.’",["except","accept","expect","excess"],"Leaving someone out = ‘except’."],
["CZ6","Fill in the blank: ‘Please ___ my apology for the delay in replying to your letter.’",["accept","except","expect","exempt"],"To take willingly = ‘accept’."],
["CZ6","Fill in the blank: ‘Keep your ticket safely; if you ___ it, you will have to pay again at the exit.’",["lose","loose","loss","lost"],"To misplace = ‘lose’ (a verb); ‘loose’ means not tight."],
["CZ6","Fill in the blank: ‘The red scarf is a perfect ___ to her blue dress.’",["complement","compliment","comment","component"],"Something that completes or goes well with another is a ‘complement’."],
["CZ6","Fill in the blank: ‘The judge paid the young lawyer a ___ on her clear argument.’",["compliment","complement","complaint","comment"],"Words of praise are a ‘compliment’."],
["CZ6","Fill in the blank: ‘A cyclone is ___, so fishermen have been told not to go out to sea.’",["imminent","eminent","prominent","imminence"],"About to happen = ‘imminent’; ‘eminent’ means distinguished."],
["CZ6","Fill in the blank: ‘Dr Rao, an ___ heart surgeon, has trained hundreds of young doctors.’",["eminent","imminent","immanent","emigrant"],"Distinguished = ‘eminent’."],
["CZ6","Fill in the blank: ‘The equator is an ___ line that runs round the middle of the earth.’",["imaginary","imaginative","imaginable","imagination"],"Not real = ‘imaginary’; ‘imaginative’ means creative."],
["CZ6","Fill in the blank: ‘The inquiry found the guard ___ in his duty, as he had left the gate open all night.’",["negligent","negligible","diligent","vigilant"],"Careless in duty = ‘negligent’; ‘negligible’ means too small to matter."],
["CZ6","Fill in the blank: ‘Luckily, the damage to the car was ___ — just a small scratch on the door.’",["negligible","negligent","neglectful","enormous"],"Too small to matter = ‘negligible’."],
["CZ6","Fill in the blank: ‘Three masked men ___ the bank and escaped with the cash.’",["robbed","stole","thieved","snatched"],"We rob a person or a place; we steal a thing."],
["CZ6","Fill in the blank: ‘Even after losing the final, the captain remained ___ and warmly praised the winners.’",["gracious","arrogant","bitter","sullen"],"Praising the winners is approving behaviour: ‘gracious’."],
["CZ6","Fill in the blank: ‘The minister’s ___ reply — a single cold “No” — upset the waiting reporters.’",["curt","detailed","warm","polite"],"A short, rude reply is ‘curt’; the others do not fit ‘a single cold No’."],

/* CZ7 articles and determiners */
["CZ7","Fill in the blank: ‘He waited for ___ hour at the bus stop before a bus came.’",["an","a","any","much"],"‘Hour’ begins with a vowel sound (silent h), so ‘an’."],
["CZ7","Fill in the blank: ‘After her degree, my sister wants to become ___ engineer.’",["an","a","the","any"],"‘Engineer’ begins with a vowel sound: ‘an’."],
["CZ7","Fill in the blank: ‘Meeting the President was ___ unique experience for the students.’",["a","an","much","any"],"‘Unique’ begins with the sound ‘yoo’, a consonant sound, so ‘a’."],
["CZ7","Fill in the blank: ‘___ Ganga flows through five states before reaching the Bay of Bengal.’",["The","A","An","Some"],"Names of rivers take ‘the’."],
["CZ7","Fill in the blank: ‘Ravi is ___ best batsman in our school team.’",["the","a","an","most"],"Superlatives take ‘the’."],
["CZ7","Fill in the blank: ‘There is not ___ water left in the tank, so use it carefully.’",["much","many","few","a few"],"‘Water’ is uncountable, so ‘much’, not ‘many’ or ‘few’."],
["CZ7","Fill in the blank: ‘Only ___ students passed the difficult test, so the teacher planned extra classes.’",["a few","a little","much","little"],"‘Students’ is countable plural: ‘a few’; ‘little’ and ‘much’ go with uncountable nouns."],
["CZ7","Fill in the blank: ‘___ student in the class has been given a library card.’",["Every","All","Many","Few"],"The singular noun and verb (‘student … has’) need ‘every’; ‘all’, ‘many’ and ‘few’ need plurals."],
["CZ7","Fill in the blank: ‘I have very ___ money left, so I cannot buy the book today.’",["little","few","many","much"],"Money is uncountable, and ‘cannot buy’ shows almost none: ‘very little’."],
["CZ7","Fill in the blank: ‘She has ___ friends in the new city, so she often feels lonely.’",["few","much","a little","plenty"],"‘Few’ (hardly any) fits ‘feels lonely’; ‘much’ and ‘a little’ go with uncountable nouns, and ‘plenty’ needs ‘of’."],
["CZ7","Fill in the blank: ‘___ honest man is respected wherever he goes.’",["An","A","Few","Many"],"‘Honest’ has a silent h, so ‘an’; ‘few’ and ‘many’ need a plural noun."],
["CZ7","Fill in the blank: ‘The school gave every child ___ uniform and a pair of shoes.’",["a","an","much","few"],"‘Uniform’ begins with the sound ‘yoo’: ‘a’."],
["CZ7","Fill in the blank: ‘He became ___ MLA at the age of thirty.’",["an","a","much","few"],"‘MLA’ is said ‘em-el-ay’, starting with a vowel sound: ‘an’."],
["CZ7","Fill in the blank: ‘___ rich should help the poor in times of need.’",["The","A","An","Much"],"‘The’ + adjective names a whole class of people: ‘the rich’."],
["CZ7","Fill in the blank: ‘Of the two brothers, Arun is ___ taller.’",["the","a","an","more"],"‘The’ + comparative is used when choosing between two: ‘the taller of the two’."],
["CZ7","Fill in the blank: ‘India is ___ large country with many languages.’",["a","an","the","much"],"‘Large’ begins with a consonant sound: ‘a’."],
["CZ7","Fill in the blank: ‘___ Ramayana was composed by the sage Valmiki.’",["The","A","An","Much"],"Holy books and epics take ‘the’."],
["CZ7","Fill in the blank: ‘My brother plays ___ flute in the school band.’",["the","a","an","much"],"Musical instruments take ‘the’: play the flute."],
["CZ7","Fill in the blank: ‘The sun rises in ___ east and sets in the west.’",["the","a","an","some"],"Directions take ‘the’."],
["CZ7","Fill in the blank: ‘___ of the two roads leads to the station, so you may take either.’",["Each","Every","All","Many"],"‘Every’ cannot be used for two, and ‘all’ and ‘many’ need a plural verb; ‘each of the two … leads’ is right."],
["CZ7","Fill in the blank: ‘The police registered ___ FIR against the driver.’",["an","a","much","few"],"‘FIR’ is said ‘ef-eye-ar’, starting with a vowel sound: ‘an’."],
["CZ7","Fill in the blank: ‘She has ___ unusual habit of reading while she walks.’",["an","a","many","few"],"‘Unusual’ begins with the vowel sound ‘uh’: ‘an’."],
["CZ7","Fill in the blank: ‘There were ___ cars on the road today than yesterday, so we reached early.’",["fewer","less","little","much"],"‘Cars’ is countable: ‘fewer’, not ‘less’."],
["CZ7","Fill in the blank: ‘He was admitted to ___ hospital near the railway station.’",["a","an","much","few"],"‘Hospital’ begins with a sounded h — a consonant sound — so ‘a’."]
);
